package org.skysongdev.skysongitems.apiimpl;

import org.bukkit.inventory.ItemStack;
import org.jetbrains.annotations.NotNull;
import org.skysongdev.skysongitems.api.ItemTemplate;
import org.skysongdev.skysongitems.utils.ItemFactory;
import org.skysongdev.skysongitems.utils.ItemLoreRenderer;
import org.skysongdev.skysongitems.utils.SkysongItem;

/**
 * An {@link ItemTemplate} backed by a parsed {@link SkysongItem}, generated by the
 * {@link ItemFactory} and then drawn by the {@link ItemLoreRenderer}, so a created item
 * shows the lines its printable properties print.
 */
final class SkysongItemTemplate implements ItemTemplate {
    private final SkysongItem template;

    SkysongItemTemplate(SkysongItem template) {
        this.template = template;
    }

    @Override
    public @NotNull ItemStack create() {
        StoredValues.requireMainThread();
        return ItemLoreRenderer.refresh(ItemFactory.create(template));
    }
}
